{
  "revised_operational_plans": [
    {
      "operational_plan_id": "R8_7_GPT_M30_V2",
      "plan_name": "R8-7-M30-V2",
      "parent_hypothesis_id": "R8-7-M30-H2",
      "tactical_thesis": "Advance Midnight's opening deployment and arts readiness, then withdraw the exposed lower support pair before repeated artillery impacts can destroy their handoff. Lava explicitly inherits unfinished eastern lower roadblock clearance before supplying lower-stop artillery damage. Mutually covered medics sustain Steward throughout the eastern artillery excursion. Gallus clears the upper western roadblock; redeployed Melantha replaces the inadequate Castle clearance assignment below. Fresh outer defenders separate officers from western civilian detention. Finally, explicitly retreat Vanilla before Midnight occupies [4,5], and add Durin for sustained central arts clearance. All completion times are falsifiable predictions, not assumed kills or executable conditional guards.",
      "selected_low_star_operator_ids": [
        "char_123_fang",
        "char_240_wyvern",
        "char_283_midn",
        "char_208_melan",
        "char_285_medic2",
        "char_212_ansel",
        "char_4227_gallus",
        "char_120_hibisc",
        "char_210_stward",
        "char_121_lava",
        "char_122_beagle",
        "char_209_ardign",
        "char_501_durin"
      ],
      "deployment_positions_and_directions": [
        {
          "operator_id": "char_123_fang",
          "tile": [3, 5],
          "direction": "UP",
          "role": "Permanent upper central blocker; assists the lower blocker and generates supported automatic DP."
        },
        {
          "operator_id": "char_240_wyvern",
          "tile": [4, 5],
          "direction": "DOWN",
          "role": "Opening lower central blocker and reciprocal damage; explicitly yields this tile to Midnight at frame 5160."
        },
        {
          "operator_id": "char_283_midn",
          "tile": [6, 4],
          "direction": "RIGHT",
          "role": "Opening lower interception, partial roadblock #4 damage and early arts; leaves at frame 2115."
        },
        {
          "operator_id": "char_208_melan",
          "tile": [1, 5],
          "direction": "RIGHT",
          "role": "Opening upper interception and eastern roadblock #3 clearance."
        },
        {
          "operator_id": "char_285_medic2",
          "tile": [5, 3],
          "direction": "RIGHT",
          "role": "Treat Midnight and Vanilla during the opening; withdraw before the previously observed artillery impact window."
        },
        {
          "operator_id": "char_212_ansel",
          "tile": [2, 6],
          "direction": "UP",
          "role": "Heal the central formation, Hibiscus and eastern damage operators."
        },
        {
          "operator_id": "char_4227_gallus",
          "tile": [2, 3],
          "direction": "DOWN",
          "role": "Ordinary arts clearance of western upper roadblock #1 after the artillery's initial upper western stop."
        },
        {
          "operator_id": "char_120_hibisc",
          "tile": [5, 6],
          "direction": "DOWN",
          "role": "Reciprocal medical coverage with Ansel; heal both central blockers and eastern damage operators."
        },
        {
          "operator_id": "char_210_stward",
          "tile": [2, 7],
          "direction": "UP",
          "role": "Continuous primary artillery damage across the eastern vertical and both eastern stops; remains through final clearance."
        },
        {
          "operator_id": "char_121_lava",
          "tile": [5, 7],
          "direction": "UP",
          "role": "Finish roadblock #4 without central-lane target competition, then attack the artillery's lower eastern stop."
        },
        {
          "operator_id": "char_122_beagle",
          "tile": [1, 5],
          "direction": "RIGHT",
          "role": "Fresh upper outer interception, separated from civilians waiting at western roadblock #1."
        },
        {
          "operator_id": "char_209_ardign",
          "tile": [6, 4],
          "direction": "RIGHT",
          "role": "Fresh lower outer interception; hold officers away from western roadblock #2."
        },
        {
          "operator_id": "char_208_melan",
          "tile": [6, 3],
          "direction": "LEFT",
          "role": "Redeployed ordinary physical clearance of western lower roadblock #2 behind Cardigan."
        },
        {
          "operator_id": "char_283_midn",
          "tile": [4, 5],
          "direction": "LEFT",
          "role": "After Vanilla explicitly retreats, inherit lower central blocking and attack both central blocking positions with repeatable arts."
        },
        {
          "operator_id": "char_501_durin",
          "tile": [5, 5],
          "direction": "DOWN",
          "role": "Medically covered sustained arts damage into both central blocking positions."
        }
      ],
      "formation_structure": {
        "opening": "Fang and Vanilla attack across adjacent central lanes. Midnight deploys at second 21, making arts available at second 61. Melantha deploys at second 30. Lancet supplies early treatment before withdrawing at second 65.",
        "medical": "Ansel [2,6] UP and Hibiscus [5,6] DOWN mutually cover each other, both central blockers, Steward, Lava and the final Durin position. Outer interception and western clearance do not receive this baseline coverage.",
        "artillery": "Steward covers the eastern vertical continuously. Lava faces UP to inherit roadblock #4 and the lower eastern artillery stop; she does not cover the upper stop. Neither highest-defense targeting nor splash damage is credited.",
        "protected_routes": "Upper clearance is Melantha on #3 followed by Gallus on #1. Lower clearance is Midnight's partial #4 work followed by Lava's completion, then redeployed Melantha on #2. Beagle at column 5 and Cardigan at column 4 prevent later officers from reaching western detention.",
        "terminal": "Fang, Midnight, both medics, Steward, Durin, Beagle and Cardigan remain. Midnight owns [4,5] only after Vanilla retreats. Durin supplies continuous arts between Midnight's active windows."
      },
      "formation_transitions": [
        {
          "frame": 1950,
          "transition": "Withdraw Lancet before the previously observed frame-1980 impact. Midnight temporarily continues without local treatment; adequate remaining HP is a survival dependency."
        },
        {
          "frame": 2115,
          "transition": "Withdraw Midnight after the opening lower runner and officer are killed. Roadblock #4 is explicitly allowed to remain unfinished and passes to Lava. No lower outer hostile is scheduled again until second 116."
        },
        {
          "frame": 2220,
          "transition": "Withdraw Melantha after the upper opening hostiles and roadblock #3 are cleared. Her 70-second redeployment cooldown then completes before second 146."
        },
        {
          "frame": 2820,
          "transition": "Lava takes the vacant eastern high ground and inherits roadblock #4. Her UP range excludes central rows 3 and 4, reducing the competition seen in the failed Durin assignment."
        },
        {
          "frame": 3330,
          "transition": "Gallus withdraws after predicted roadblock #1 completion; Beagle occupies Melantha's already vacant upper ground tile before the paired officers arrive."
        },
        {
          "frame": 3720,
          "transition": "Cardigan establishes fresh lower interception before the first paired officer reaches [6,4]. Midnight's opening enemies must already be dead."
        },
        {
          "frame": 4380,
          "transition": "Lava's lower-stop coverage has ended; transfer her slot to Melantha for roadblock #2. This is a coverage-window handoff, not an assumed artillery-death gate. Steward and both medics remain."
        },
        {
          "frame": 5160,
          "transition": "Retreat Melantha after predicted roadblock #2 completion, then retreat Vanilla explicitly. Deploy Midnight on the now-free [4,5], followed by Durin on [5,5]. Blocking changes hands in the listed same-frame order."
        }
      ],
      "corridor_responsibilities": [
        {
          "routes": ["route-0"],
          "responsibility": "No scheduled hostile duty."
        },
        {
          "routes": ["route-1"],
          "responsibility": "Steward is the continuous artillery attacker under reciprocal medical support. Midnight may contribute during the opening crossing, and Lava contributes at the lower eastern stop. Require recorded artillery death before it escapes eastern coverage; do not credit particular target ordering."
        },
        {
          "routes": ["route-2"],
          "responsibility": "Melantha clears #3 and the opening upper officer; Gallus clears #1. Beagle intercepts later officers at column 5. Record complete safe arrival of the first civilian, independently of roadblock destruction."
        },
        {
          "routes": ["route-15"],
          "responsibility": "Midnight damages #4; Lava must finish it before the paired officers enter its vicinity. Cardigan holds at column 4 while Melantha clears #2 from column 3. Record the second civilian's complete safe arrival."
        },
        {
          "routes": ["route-3", "route-4", "route-12", "route-13", "route-20", "route-21", "route-30", "route-31"],
          "responsibility": "Fang retains upper central traffic. Vanilla initially assists; final Midnight and Durin provide sustained clearance, including armored enemies."
        },
        {
          "routes": ["route-5", "route-6", "route-11", "route-14", "route-18", "route-19", "route-28", "route-29"],
          "responsibility": "Vanilla retains lower central traffic until frame 5160; Midnight then inherits the same blocking position under both medics. Fang and Durin assist."
        },
        {
          "routes": ["route-7", "route-8", "route-17", "route-22", "route-23", "route-24"],
          "responsibility": "Melantha handles the opening; Beagle handles paired and final officers using ordinary three-block interception and attacks. Retain Beagle until her entire queue is dead."
        },
        {
          "routes": ["route-9", "route-10", "route-16", "route-25", "route-26", "route-27"],
          "responsibility": "Midnight must kill both opening hostiles before withdrawal; Cardigan handles paired and final officers. No unsupported self-healing is credited."
        }
      ],
      "pressure_window_responsibilities": [
        {
          "window_seconds": [0, 74],
          "responsibility": "Establish reciprocal central damage and survival-dependent DP. Bring Midnight's arts forward to second 61, remove Lancet at 65 and Midnight at 70.5, and finish the upper opening before Melantha leaves."
        },
        {
          "window_seconds": [47, 114],
          "responsibility": "Gallus clears #1 while both medics establish reciprocal coverage. Steward begins the primary artillery window. Lava inherits and finishes #4; her clearance deadline must precede nearby paired officers."
        },
        {
          "window_seconds": [111, 158],
          "responsibility": "Establish fresh outer defenders, maintain eastern artillery output and verify the upper civilian's arrival. Lava's departure does not remove Steward's continuing responsibility."
        },
        {
          "window_seconds": [146, 185],
          "responsibility": "Melantha clears #2 behind Cardigan, then yields her slot to terminal arts support. Verify the lower civilian's arrival and execute the explicit Vanilla-to-Midnight handoff."
        },
        {
          "window_seconds": [172, 211],
          "responsibility": "Keep all four hostile corridors staffed through final runners, officers and armored spawns. Durin supplies immediate arts while Midnight charges."
        },
        {
          "window_seconds": [211, null],
          "responsibility": "Clear all retained enemies with continuous treatment, Durin and Midnight's arts windows. Keep outer defenders until their queues are empty and enforce the complete acceptance predicate."
        }
      ],
      "skill_intents": [
        {
          "operator_id": "char_123_fang",
          "intent": "Automatic +6 DP is expected at seconds 19,44,69 and every 25 seconds thereafter while alive and deployed. Opening purchases depend on actual survival and grants."
        },
        {
          "operator_id": "char_240_wyvern",
          "frames": [750, 1650, 2550, 3450, 4350],
          "intent": "Supported manual ATK and +6 DP at seconds 25,55,85,115,145; respect the 10-second active SP pause. No further grants are budgeted after her second-172 retreat."
        },
        {
          "operator_id": "char_283_midn",
          "frames": [1830, 6360, 9660],
          "intent": "Opening arts at second 61 accelerates the lower officer kill and remaining device or artillery attacks without assuming priority. Redeployment at 172 resets readiness to 212; the next activation is 322 after 40 active and 70 charging seconds."
        },
        {
          "operator_id": "char_208_melan",
          "frames": [2100],
          "intent": "ATK enhancement at second 70 finishes the opening upper duty. No skill is available during her short second deployment, so western #2 clearance relies on ordinary attacks."
