        {
          "operator_id": "char_212_ansel",
          "frames": [2070, 3870, 5670, 7470, 9270, 11070],
          "intent": "Healing enhancement at seconds 69,129,189,249,309,369; include the 25-second active SP pause and exclude probabilistic extra healing."
        },
        {
          "operator_id": "char_120_hibisc",
          "frames": [2640, 4140, 5640, 7140, 8640, 10140, 11640],
          "intent": "Healing enhancement at seconds 88,138,188,238,288,338,388; include the 20-second active SP pause and exclude unsupported talent ATK."
        },
        {
          "operator_id": "char_121_lava",
          "frames": [3120],
          "intent": "Deployment grants supported 30 SP, making activation legal at second 104. Accelerate ordinary single-target arts to complete #4 and catch the beginning of the lower artillery stop; do not credit splash geometry."
        },
        {
          "operator_id": "char_122_beagle",
          "frames": [4530],
          "intent": "DEF enhancement at second 151 provides a buffer against possible remaining artillery exposure. It is not credited as meaningful improvement against officers already near minimum physical damage."
        },
        {
          "operator_id": "char_210_stward",
          "intent": "Use supported automatic enhanced attacks. Do not assume highest-defense target priority or unsupported talent ATK."
        },
        {
          "operator_ids": ["char_4227_gallus", "char_501_durin", "char_209_ardign"],
          "intent": "Ordinary attacks and supported blocking only; exclude Gallus RES reduction, Durin evasion and Cardigan self-healing."
        }
      ],
