      "battle_phases": [
        {
          "phase_id": "P1_OPENING_ESCAPE",
          "goal": "Survive all four opening hostile corridors and escape repeated lower artillery impacts.",
          "start_condition": "Stage starts with 10 DP and no operators deployed.",
          "completion_condition": "By frame 2220, opening outer hostiles and #3 are dead; Midnight, Lancet and Melantha have completed their scheduled withdrawals.",
          "responsibilities": [
            "Fang and Vanilla jointly kill central opening runners while producing the grants needed by subsequent deployments.",
            "Midnight uses second-61 arts to finish the lower officer; remaining #4 clearance belongs to Lava.",
            "Melantha clears the upper opening and #3, using her second-70 skill if still required."
          ],
          "survival_dependencies": [
            "Lancet's treatment must leave Midnight healthy enough for exposure before frame 2115.",
            "Earlier deployment changes target interactions; the prior frame-1980 impact is evidence of danger, not a guaranteed future clock.",
            "Fang and Vanilla must survive to produce their budgeted grants."
          ],
          "handoff_requirements": [
            "Both opening lower hostiles must die before Midnight retreats; an injured survivor is not a completed interception duty.",
            "Melantha must finish #3 before leaving; Midnight need not finish #4."
          ],
          "failure_effect_on_later_phases": "A surviving outer hostile can leak during the empty interval; an early source death also invalidates later commands or DP-funded deployments."
        },
        {
          "phase_id": "P2_UPPER_WEST_AND_MEDICINE",
          "goal": "Open the upper western escape path while establishing durable eastern medical coverage.",
          "start_condition": "Gallus deploys at frame 1410 while the opening continues.",
          "completion_condition": "Roadblock #1 is destroyed before Gallus leaves at frame 3330, and both medics remain active with Steward.",
