          ],
          "survival_dependencies": [
            "Gallus must survive without baseline medical coverage.",
            "Neither unsupported Gallus RES reduction nor medic talent multipliers are included."
          ],
          "handoff_requirements": [
            "Verify #1 destruction and the first civilian's complete arrival separately.",
            "Beagle takes the upper outer corridor before the paired officers reach column 5."
          ],
          "failure_effect_on_later_phases": "An unfinished #1 leaves the first civilian detained during the western artillery return; medical collapse removes the primary artillery attacker."
        },
        {
          "phase_id": "P3_EASTERN_CLEARANCE",
          "goal": "Finish #4 and kill the artillery within its viable eastern damage window.",
          "start_condition": "Lava deploys at frame 2820 facing UP.",
          "completion_condition": "Predict #4 destruction by frame 3420 and recorded artillery death by frame 4740.",
          "responsibilities": [
            "Lava completes inherited #4 damage before nearby paired officers threaten the detained lower civilian.",
            "Steward attacks across both eastern stops; Lava supplements the lower stop.",
            "Both medics preserve the damage formation while central blockers retain passing hostiles."
          ],
          "survival_dependencies": [
            "Steward and both medics must remain alive; one artillery hit or partial accumulated damage is insufficient.",
            "Outer officers can compete for Lava's attacks; no target ordering or splash multiplication is assumed."
          ],
          "handoff_requirements": [
            "Cardigan must establish lower interception at frame 3720.",
            "Lava's frame-4380 withdrawal follows the end of her lower-stop coverage, while Steward remains responsible for any surviving artillery."
          ],
          "failure_effect_on_later_phases": "A living artillery unit leaving eastern coverage threatens protected routes and can leak. Early Steward death is a failed survival responsibility, not permission to assume Lava completed the kill."
        },
        {
          "phase_id": "P4_LOWER_WESTERN_ESCAPE",
          "goal": "Release the second civilian from its final obstacle under independent officer interception.",
          "start_condition": "Lava withdraws and Melantha redeploys at frame 4380.",
          "completion_condition": "Roadblock #2 is destroyed before frame 5160 and the second civilian subsequently reaches its objective safely.",
          "responsibilities": [
            "Melantha attacks #2 from [6,3] LEFT with ordinary physical damage.",
            "Cardigan retains officers at [6,4], separating them from the civilian waiting farther west.",
            "Beagle independently maintains the upper outer corridor."
          ],
          "survival_dependencies": [
            "Melantha has completed redeployment cooldown and is not assigned unsupported healing or a second-deployment skill.",
            "Cardigan must retain enough blocking capacity and HP throughout device clearance."
          ],
          "handoff_requirements": [
            "Check actual #2 destruction before treating Melantha's scheduled withdrawal as successful.",
            "Record the second civilian's arrival; release alone does not satisfy the objective."
          ],
          "failure_effect_on_later_phases": "An unfinished #2 preserves civilian exposure even if the artillery is dead; losing Cardigan permits officers to reach the civilian or leak."
        },
        {
          "phase_id": "P5_TERMINAL_HANDOFF",
          "goal": "Establish medically covered arts clearance without leaving a central lane unblocked.",
          "start_condition": "Frame 5160 begins with Vanilla owning [4,5].",
          "completion_condition": "Melantha and Vanilla retreat in order; Midnight owns [4,5], Durin occupies [5,5], and all final spawns through frame 6330 remain contained.",
